export function openNotebookPopup(container,title,sections){
 const doc=container.ownerDocument,root=doc.createElement('section');root.className='np-window';root.setAttribute('role','dialog');root.setAttribute('aria-label',title);const style=doc.createElement('style');style.textContent='.np-window{pointer-events:auto;position:absolute;inset:0;z-index:60;background:#17120ddd;display:flex;align-items:center;justify-content:center;font-family:"Songti SC",serif;color:#644b32}.np-card{width:min(900px,92%);max-height:86%;box-sizing:border-box;overflow:auto;background:#f1e4ca;border:1px solid #aa8c5e;border-radius:7px;padding:24px 30px;box-shadow:0 15px 65px #0007;font-size:clamp(14px,2vw,24px)}.np-card header{display:flex;align-items:center;gap:24px;margin-bottom:20px}.np-card h2{font-size:1.3em;font-weight:500;margin:0;flex:1}.np-card button{border:0;background:none;color:#92704b;font:1.3em serif;cursor:pointer;min-width:44px;min-height:44px}.np-card article{padding:16px 0;border-top:1px dashed #b8a07a66}.np-card strong{font-weight:500;color:#74583d}.np-card small{display:block;margin:7px 0;color:#a0855f;font-size:.85em}.np-card p{line-height:1.6;white-space:pre-wrap;margin:7px 0;color:#796249}';
 const panel=doc.createElement('div');panel.className='np-card';const header=doc.createElement('header'),h=doc.createElement('h2'),close=doc.createElement('button');h.textContent=title;close.textContent='×';close.setAttribute('aria-label','关闭详情');close.addEventListener('click',()=>root.remove());header.append(h,close);panel.append(header);
 for(const section of sections){const article=doc.createElement('article'),name=doc.createElement('strong'),time=doc.createElement('small'),content=doc.createElement('p');name.textContent=section.title;time.textContent=section.time??'';content.textContent=(section.details??[]).join('\n');article.append(name,time,content);panel.append(article);}if(!sections.length){const p=doc.createElement('p');p.textContent='暂无记录';panel.append(p);}root.append(style,panel);container.append(root);root.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();root.remove();}});return root;
}
